-- ============================================================
-- LEGAL DOCUMENTS CMS
-- Converts the previously hardcoded static legal pages (terms,
-- privacy, disclaimer, refund-policy, copyright) into DB-driven,
-- admin-editable content with full version history. The seed
-- content below was extracted directly (byte-for-byte, via
-- rendering the actual page components to static HTML) from the
-- existing pages, not retyped, to guarantee no legal content
-- drifted during the migration.
-- ============================================================

CREATE TABLE IF NOT EXISTS legal_documents (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  slug TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  content TEXT NOT NULL,  -- HTML content (inline-styled, matches theme vars)
  version INTEGER NOT NULL DEFAULT 1,
  updated_by UUID REFERENCES profiles(id) ON DELETE SET NULL,
  published_at TIMESTAMPTZ DEFAULT NOW(),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Append-only history — every save creates a snapshot here before
-- updating the live row, so there's a real audit trail of exactly
-- what your terms/privacy policy said on any given date (this
-- matters legally: you may need to prove what users agreed to at
-- a specific point in time).
CREATE TABLE IF NOT EXISTS legal_document_revisions (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  document_id UUID NOT NULL REFERENCES legal_documents(id) ON DELETE CASCADE,
  slug TEXT NOT NULL,
  title TEXT NOT NULL,
  content TEXT NOT NULL,
  version INTEGER NOT NULL,
  updated_by UUID REFERENCES profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS legal_document_revisions_document_idx ON legal_document_revisions(document_id);

ALTER TABLE legal_documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE legal_document_revisions ENABLE ROW LEVEL SECURITY;

-- Public can read published legal documents (they're shown on public,
-- logged-out pages) — nothing sensitive here, this is intentional.
CREATE POLICY "legal_documents_public_read" ON legal_documents
  FOR SELECT USING (true);

-- Only admins can write, and only admins can see revision history.
CREATE POLICY "legal_documents_admin_write" ON legal_documents
  FOR INSERT WITH CHECK (is_admin());
CREATE POLICY "legal_documents_admin_update" ON legal_documents
  FOR UPDATE USING (is_admin());
CREATE POLICY "legal_document_revisions_admin_read" ON legal_document_revisions
  FOR SELECT USING (is_admin());
CREATE POLICY "legal_document_revisions_admin_write" ON legal_document_revisions
  FOR INSERT WITH CHECK (is_admin());

-- Seed with the exact existing content (extracted from the live
-- static pages, not rewritten) so nothing changes for users on
-- deploy day — only the *editing mechanism* changes.
INSERT INTO legal_documents (slug, title, content, published_at) VALUES
  ('terms', 'Terms of Service', '<div style="font-size:15px;line-height:1.7;color:var(--text-secondary)"><p>These Terms of Service (&quot;Terms&quot;) govern your access to and use of Finora (the &quot;Service&quot;), a software product owned and operated by WEALTHOS (&quot;WEALTHOS,&quot; &quot;we,&quot; &quot;us,&quot; or &quot;our&quot;). By creating an account or using the Service, you agree to these Terms. If you do not agree, do not use the Service.</p><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">1. Not Financial, Tax, or Legal Advice</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Finora provides tools for tracking, calculating, and visualizing your own financial information — including the Financial Toolkit&#x27;s calculators, AI Coach, and Support Chat.<strong> Nothing in the Service constitutes financial, investment, tax, or legal advice, or a recommendation to buy, sell, or hold any security or asset.</strong> Calculator outputs and AI responses are estimates based on the assumptions you provide and can be wrong. Always consult a qualified, licensed professional before making financial decisions.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">2. Your Account</h2><div style="display:flex;flex-direction:column;gap:10px"><p>You must provide accurate information and keep your login credentials confidential. You are responsible for all activity under your account. Notify us immediately of any unauthorized use.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">3. Subscriptions &amp; Billing</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Paid plans renew automatically for the same term until canceled. You can cancel anytime from Settings → Billing; cancellation takes effect at the end of the current billing period, and you retain access until then. See our <a href="/legal/refund-policy" style="color:var(--text-green)">Refund Policy</a> for details on refunds.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">4. Acceptable Use</h2><div style="display:flex;flex-direction:column;gap:10px"><p>You agree not to:</p><ul><li>Use the Service for any unlawful purpose or to violate any applicable law</li><li>Attempt to gain unauthorized access to any account, system, or network related to the Service</li><li>Reverse engineer, scrape, or interfere with the Service&#x27;s normal operation</li><li>Upload malicious code or attempt to disrupt the Service&#x27;s availability</li><li>Use the Service to impersonate any person or entity</li></ul></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">5. User Content</h2><div style="display:flex;flex-direction:column;gap:10px"><p>You retain ownership of the financial data and content you enter into the Service. You grant us a limited license to store, process, and display that content solely to provide the Service to you.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">6. Intellectual Property</h2><div style="display:flex;flex-direction:column;gap:10px"><p>The Service, including its design, code, calculators, and branding, is owned by WEALTHOS and protected by intellectual property laws. See our <a href="/legal/copyright" style="color:var(--text-green)">Copyright Notice</a>. Except as expressly permitted, you may not copy, modify, or create derivative works of the Service.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">7. Third-Party Services</h2><div style="display:flex;flex-direction:column;gap:10px"><p>The Service integrates third-party providers (e.g. payment processing, AI inference, hosting). We are not responsible for the acts or omissions of third parties, though we select providers we believe are reputable and secure.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">8. Disclaimer of Warranties</h2><div style="display:flex;flex-direction:column;gap:10px"><p>THE SERVICE IS PROVIDED &quot;AS IS&quot; AND &quot;AS AVAILABLE,&quot; WITHOUT WARRANTIES OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE, AND NON-INFRINGEMENT. WE DO NOT WARRANT THAT THE SERVICE WILL BE UNINTERRUPTED, ERROR-FREE, OR THAT ANY CALCULATION OR AI OUTPUT WILL BE ACCURATE. See our full <a href="/legal/disclaimer" style="color:var(--text-green)">Disclaimer</a>.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">9. Limitation of Liability</h2><div style="display:flex;flex-direction:column;gap:10px"><p>TO THE MAXIMUM EXTENT PERMITTED BY LAW, WEALTHOS SHALL NOT BE LIABLE FOR ANY INDIRECT, INCIDENTAL, SPECIAL, CONSEQUENTIAL, OR PUNITIVE DAMAGES, OR ANY LOSS OF PROFITS, DATA, OR FINANCIAL LOSS ARISING FROM YOUR USE OF, OR RELIANCE ON, THE SERVICE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGES.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">10. Account Termination</h2><div style="display:flex;flex-direction:column;gap:10px"><p>You may delete your account at any time from Settings. We may suspend or terminate your access if you violate these Terms, engage in fraudulent or abusive behavior, or as required by law.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">11. Governing Law</h2><div style="display:flex;flex-direction:column;gap:10px"><p style="background:rgba(255,159,10,0.08);border:1px solid rgba(255,159,10,0.2);border-radius:8px;padding:10px 14px"><strong>⚠ Placeholder — replace before publishing.</strong> These Terms are governed by the laws of <strong>[Your State/Country]</strong>, without regard to conflict-of-law principles, and any dispute arising from these Terms or the Service will be resolved in the courts located in<strong> [Your City, State/Country]</strong>. Fill in your actual jurisdiction — this depends on where your business is incorporated/operated, which isn&#x27;t something to guess.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">12. Changes to These Terms</h2><div style="display:flex;flex-direction:column;gap:10px"><p>We may update these Terms from time to time. Continued use of the Service after changes take effect constitutes acceptance of the updated Terms.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">13. Contact</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Questions about these Terms? Visit our <a href="/contact" style="color:var(--text-green)">Contact page</a>.</p></div></section>', '2026-07-24'::timestamptz),
  ('privacy', 'Privacy Policy', '<div style="font-size:15px;line-height:1.7;color:var(--text-secondary)"><p>This Privacy Policy explains how WEALTHOS (&quot;WEALTHOS,&quot; &quot;we,&quot; &quot;us,&quot; or &quot;our&quot;), the operator of Finora, collects, uses, shares, and protects information when you use our website, mobile application, and related services (collectively, the &quot;Service&quot;).</p><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">1. Information We Collect</h2><div style="display:flex;flex-direction:column;gap:10px"><p><strong>Account information.</strong> Name, email address, username, and password (stored by our authentication provider as a one-way hash — we never see or store your plaintext password).</p><p><strong>Financial information you provide.</strong> Assets, liabilities, portfolio holdings, budgets, income, transactions, and financial goals you manually enter or connect to the Service. Finora does not initiate bank transfers or move money on your behalf.</p><p><strong>Usage data.</strong> Device information, IP address, log data, and how you interact with the Service, collected automatically to keep the Service secure and improve it.</p><p><strong>Payment information.</strong> Subscription payments are processed by Stripe. We do not store your full card number; Stripe provides us only the information necessary to manage your subscription (e.g. plan, status, last four digits).</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">2. How We Use Information</h2><div style="display:flex;flex-direction:column;gap:10px"><ul><li>To provide, maintain, and improve the Service (dashboards, calculators, reports, AI features)</li><li>To authenticate you and secure your account</li><li>To process subscription payments and communicate about your account</li><li>To respond to support requests</li><li>To detect, investigate, and prevent fraud, abuse, and security incidents</li><li>To comply with legal obligations</li></ul></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">3. AI Features</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Features such as the AI Coach and Support Chat send the text you submit, and limited account context necessary to answer your question, to our AI infrastructure providers (currently Groq) to generate a response. We do not use your individual financial data to train third-party foundation models.</p><p><strong>Voice features.</strong> If you use voice-based AI interactions, your audio is sent to our speech-to-text and text-to-speech processing services solely to transcribe your request and generate a spoken response. Transcripts may be stored to maintain conversation history within the Service and can be deleted by deleting your account.</p><p><strong>AI memory.</strong> To let AI features recall relevant context from earlier in a conversation, portions of your AI conversations may be stored as vector embeddings in a dedicated AI memory database. This is used only to improve the relevance of AI responses within your own account and is deleted when your account is deleted.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">4. Cookies</h2><div style="display:flex;flex-direction:column;gap:10px"><p>We use strictly necessary cookies to keep you signed in and to maintain your session security. These cookies are essential to the Service functioning and cannot be disabled without preventing sign-in. We do not currently use advertising or cross-site tracking cookies.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">5. Analytics</h2><div style="display:flex;flex-direction:column;gap:10px"><p>We use a product analytics provider (currently PostHog) to understand how the Service is used — for example, which features are used most, to find and fix bugs, and to guide what we build next. This is usage data about how the app is used, not the content of your financial records. We also use an error-monitoring provider (currently Sentry) to automatically detect and diagnose crashes and bugs; error reports can include technical context (like the page you were on and non-sensitive request metadata) but are configured to avoid capturing passwords or full financial account details.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">6. How We Share Information</h2><div style="display:flex;flex-direction:column;gap:10px"><p>We do not sell your personal information. We share information only with:</p><ul><li>Service providers who process data on our behalf — hosting and database (Supabase), payments (Stripe), transactional email (Resend), AI inference (Groq), product analytics (PostHog), and error monitoring (Sentry) — each bound by confidentiality obligations</li><li>Law enforcement or regulators, when required by law or to protect rights, safety, or property</li><li>A successor entity, in the event of a merger, acquisition, or asset sale — with notice to you</li></ul></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">7. Data Security</h2><div style="display:flex;flex-direction:column;gap:10px"><p>We use industry-standard safeguards, including encryption in transit, row-level database access controls scoped to your account, and password hashing. No method of transmission or storage is 100% secure, and we cannot guarantee absolute security.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">8. Data Retention &amp; Deletion</h2><div style="display:flex;flex-direction:column;gap:10px"><p>We retain your information for as long as your account is active or as needed to provide the Service. You may permanently delete your account and associated data at any time from Settings → Delete Account. Deletion is irreversible and removes your profile, financial data, and portfolio history from our systems, subject to any backup retention or legal record-keeping requirements described in Section 8.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">9. Your Rights</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Depending on your location, you may have rights to access, correct, export, or delete your personal information, and to object to or restrict certain processing. Contact us (see the Contact page) to exercise these rights.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">10. Backups</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Our database provider maintains automated backups for disaster-recovery purposes. Data deleted from active systems may persist in encrypted backups for a limited period before being purged on a rolling schedule.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">11. Children&#x27;s Privacy</h2><div style="display:flex;flex-direction:column;gap:10px"><p>The Service is not directed to individuals under 18, and we do not knowingly collect information from children.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">12. Changes to This Policy</h2><div style="display:flex;flex-direction:column;gap:10px"><p>We may update this Privacy Policy from time to time. We will post the updated version with a new &quot;Last updated&quot; date, and, where changes are material, provide additional notice.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">13. Contact Us</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Questions about this Privacy Policy? Visit our <a href="/contact" style="color:var(--text-green)">Contact page</a>.</p></div></section>', '2026-07-24'::timestamptz),
  ('disclaimer', 'Disclaimer', '<div style="font-size:15px;line-height:1.7;color:var(--text-secondary)"><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Not Financial, Investment, Tax, or Legal Advice</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Finora is a software tool for tracking, calculating, and visualizing financial information you provide. It is <strong>not</strong> a registered investment adviser, broker-dealer, accountant, or law firm, and nothing on the Service — including dashboard figures, the Financial Toolkit&#x27;s calculators, AI Coach responses, or Support Chat responses — constitutes financial, investment, tax, accounting, or legal advice, or a recommendation to buy, sell, or hold any security, property, or asset.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Calculators &amp; Projections</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Every calculator in the Financial Toolkit (retirement, FIRE, mortgage, rent vs. buy, debt payoff, and others) produces estimates based entirely on the assumptions you enter — expected return, inflation, interest rates, and so on. Real-world results depend on markets, rates, and personal circumstances that cannot be predicted, and actual outcomes will differ, potentially substantially, from any projection shown.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">AI-Generated Content</h2><div style="display:flex;flex-direction:column;gap:10px"><p>AI Coach and Support Chat use large language models to generate responses. These responses can be incomplete, outdated, or simply wrong. AI output should never be your sole basis for a financial decision.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">No Guarantee of Accuracy</h2><div style="display:flex;flex-direction:column;gap:10px"><p>While we aim for accuracy, Finora does not guarantee that any figure, calculation, market data point, or report generated by the Service is complete, current, or error-free.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Your Responsibility</h2><div style="display:flex;flex-direction:column;gap:10px"><p>You are solely responsible for your financial decisions. Before acting on any information from the Service, consult a licensed financial advisor, accountant, or attorney qualified to advise you on your specific situation.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Related Policies</h2><div style="display:flex;flex-direction:column;gap:10px"><p>This Disclaimer supplements our <a href="/legal/terms" style="color:var(--text-green)">Terms of Service</a> and <a href="/legal/privacy" style="color:var(--text-green)">Privacy Policy</a>.</p></div></section>', '2026-07-24'::timestamptz),
  ('refund-policy', 'Refund Policy', '<div style="font-size:15px;line-height:1.7;color:var(--text-secondary)"><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">All Sales Are Final</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Subscription payments made to WEALTHOS for Finora are <strong>non-refundable</strong>, except where required by applicable law. This applies to monthly and annual subscription charges, including partial billing periods after a cancellation or downgrade.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Cancel Anytime</h2><div style="display:flex;flex-direction:column;gap:10px"><p>You can cancel your subscription at any time from Settings → Billing. Cancellation stops future renewals, but does not refund the current billing period — you&#x27;ll keep access to your plan&#x27;s features until the end of the period you already paid for.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Billing Errors</h2><div style="display:flex;flex-direction:column;gap:10px"><p>If you believe you were charged in error (e.g. a duplicate charge or a charge after you canceled), contact us within 30 days via the <a href="/contact" style="color:var(--text-green)">Contact page</a> and we&#x27;ll investigate. This exception is limited to genuine billing errors, not a general right to request a refund for a change of mind.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Chargebacks</h2><div style="display:flex;flex-direction:column;gap:10px"><p>Please contact us before filing a chargeback with your bank or card issuer — we&#x27;re able to resolve most billing issues directly and faster than a chargeback dispute.</p></div></section><section style="margin-top:28px"><h2 style="font-size:17px;font-weight:700;color:var(--text-primary);margin-bottom:10px">Acknowledgment</h2><div style="display:flex;flex-direction:column;gap:10px"><p>By subscribing to a paid Finora plan, you acknowledge and agree to this Refund Policy. This policy is also referenced on the Billing page before you complete a purchase.</p></div></section>', '2026-07-24'::timestamptz),
  ('copyright', 'Copyright Notice', '<div style="font-size:15px;line-height:1.7;color:var(--text-secondary)"><p>© 2026 WEALTHOS. All rights reserved.</p><p style="margin-top:16px">Finora is a product of WEALTHOS.</p><p style="margin-top:16px">All content, design, source code, calculators, graphics, logos, and branding that make up the Finora Service are the property of WEALTHOS or its licensors and are protected by copyright, trademark, and other intellectual property laws. No part of the Service may be reproduced, distributed, publicly displayed, or used to create derivative works without prior written permission, except as expressly permitted under our <a href="/legal/terms" style="color:var(--text-green)">Terms of Service</a>.</p><p style="margin-top:16px">Your own financial data that you enter into the Service remains yours — this notice covers the Finora platform itself, not your personal content.</p><p style="margin-top:16px">If you believe content on the Service infringes your copyright, contact us via the <a href="/contact" style="color:var(--text-green)">Contact page</a> with a description of the work and the alleged infringement, and we will investigate.</p>', '2026-07-24'::timestamptz)
ON CONFLICT (slug) DO NOTHING;
